// Serialize mutations so rapid clicks cannot overwrite an active draft or checkout.
let queue=Promise.resolve();function run(fn){queue=queue.then(fn).catch(e=>{console.error(e);toast(e.message||'Something went wrong. Please try again.',true)});return queue}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;if(el.dataset.action==='close'){closeModal();return}if(el.dataset.action==='pdf-share'){shareCurrentPDF();return}if(el.dataset.action==='open-whatsapp'){window.open('https://wa.me/','_blank','noopener,noreferrer');return}const action=actions[el.dataset.action];if(action)run(async()=>{if(['confirm-clear','confirm-import','merge-scan','scan-bill','seed'].includes(el.dataset.action)&&!await managerApproval('Approve '+el.dataset.action.replaceAll('-',' ')))return;return action(el)})});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;run(async()=>{if(!form.reportValidity())return;if(['line-form','discount-form','cancel-form','product-form','settings-form'].includes(form.id)&&!await managerApproval('Approve this change'))return;const data=Object.fromEntries(new FormData(form));switch(form.id){
 case 'credit-form':{const total=totals(state.cart,state.discount).total,paid=Math.round(+data.paid*100);if(!Number.isSafeInteger(paid)||paid<0||paid>total)throw Error('Invalid amount paid.');state.customer=data.customer.trim();await completeSale([{method:data.method,amount:paid},{method:'Credit',amount:total-paid}].filter(p=>p.amount));break}
 case 'line-form':{const l=state.cart.find(l=>l.id===form.dataset.id),price=Math.round(+data.price*100),discount=+data.discount;if(!Number.isFinite(price)||price<0||!Number.isFinite(discount)||discount<0||discount>100)throw Error('Enter a valid price and discount.');if(l.price!==price)await log('Price override',`${l.name}: ${money(l.price)} → ${money(price)} · ${data.reason}`);if(l.discount!==discount)await log('Manual discount',`${l.name}: ${l.discount}% → ${discount}% · ${data.reason}`);l.price=price;l.discount=discount;await saveDraft();closeModal();renderCart();break}
 case 'discount-form':{const value=+data.discount;if(!Number.isFinite(value)||value<0||value>100)throw Error('Discount must be 0–100%.');await log('Invoice discount',`${state.discount}% → ${value}% · ${data.reason}`);state.discount=value;await saveDraft();closeModal();renderCart();break}
 case 'customer-form':state.customer=data.customer.trim();await saveDraft();closeModal();renderCart();break;
 case 'payment-form':{const total=totals(state.cart,state.discount).total;let payments;if(data.method==='Split'){payments=[{method:'Cash',amount:Math.round(+data.cash*100)},{method:'Card',amount:Math.round(+data.card*100)},{method:'UPI',amount:Math.round(+data.upi*100)}].filter(p=>p.amount);if(payments.reduce((a,p)=>a+p.amount,0)!==total)throw Error('Split amounts must exactly match the total.')}else{if(data.method==='Cash'&&Math.round(+data.received*100)<total)throw Error('Cash received is less than the amount due.');payments=[{method:data.method,amount:total}]}if(data.method!=='Cash'&&!data.verified)throw Error('Verify receipt of payment before completing the sale.');await completeSale(payments,!!data.print);break}
 case 'product-form':{const existing=state.products.find(p=>p.id===form.dataset.id);const p=validateProduct({...existing,...data,id:existing?.id||uid(),name:data.name.trim(),sku:data.sku.trim(),barcode:data.barcode.trim(),category:data.category.trim(),price:Math.round(+data.price*100),cost:Math.round(+data.cost*100),stock:+data.stock,tax:+data.tax,art:existing?.art??-1});await db.transaction('rw',db.products,db.audit,async()=>{const products=await db.products.toArray();if(products.some(x=>x.id!==p.id&&(x.sku===p.sku||x.barcode===p.barcode||(p.serial&&x.serial===p.serial))))throw Error('SKU, barcode and serial numbers must be unique.');await db.products.put(p);await audit(existing?'Product updated':'Product added',`${p.name} · stock ${p.stock} · price ${money(p.price)}`,state.settings.cashier);if(existing&&existing.price!==p.price)await audit('Price override',`${p.name}: ${money(existing.price)} → ${money(p.price)} · inventory edit`,state.settings.cashier)});await refresh();closeModal();renderPage();toast('Product saved.');break}
 case 'settings-form':await saveStoreSettings(data);toast('Store settings saved.');break;
 case 'cancel-form':await cancelSale(form.dataset.id,data.reason.trim(),state.settings.cashier);await refresh();closeModal();renderPage();toast('Bill cancelled and stock restored. Arrange any payment refund separately.');break;
 }})});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.purchaseField){state.purchaseMeta={...state.purchaseMeta,[el.dataset.purchaseField]:el.value};updateReviewTotals()}else if(el.id==='search'){state.query=el.value;state.limit=48;renderProducts()}else if(['inventory-search','sales-search'].includes(el.id)){state.query=el.value;const pos=el.selectionStart;const id=el.id;state.page==='inventory'?inventoryView():salesView();const next=$('#'+id);next.focus();next.setSelectionRange(pos,pos);icons()}else if(el.id==='gemini-key')state.scanKey=el.value;else if(el.dataset.scanIndex!==undefined){const r=state.scanRows[+el.dataset.scanIndex];r[el.dataset.field]=el.type==='number'?(el.value===''?'':Number(el.value)):el.value;updateReviewTotals()}else if(el.id==='cash-received'){$('#cash-change').textContent=money(Math.max(0,Math.round(+el.value*100)-totals(state.cart,state.discount).total))}else if(el.hasAttribute('data-split')){const paid=[...document.querySelectorAll('[data-split]')].reduce((a,x)=>a+Math.round(+x.value*100),0);$('#split-remaining').textContent='Remaining: '+money(totals(state.cart,state.discount).total-paid)}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='pdf-paper')run(()=>showDocument(currentPDF.record,currentPDF.kind,currentPDF.sourceImage,el.value));if(el.dataset.qty)run(async()=>{try{await setQty(el.dataset.qty,+el.value)}catch(e){renderCart();throw e}});if(el.id==='invoice-file')run(()=>loadImage(el.files[0]));if(el.id==='inventory-file')run(()=>readInventory(el.files[0]))});
document.addEventListener('dragover',e=>{if(e.target.closest('#drop-zone'))e.preventDefault()});document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();run(()=>loadImage(e.dataTransfer.files[0]))}});
$('#modal').addEventListener('cancel',()=>stopCamera());$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
let barcodeBuffer='',barcodeLast=0;
document.addEventListener('keydown',e=>{
 const typing=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);
 if(e.key==='Escape'){if($('#modal').open)return;if(state.page==='pos'){e.preventDefault();actions.clear()}return}
 if(['F1','F2','F3','F4','F8'].includes(e.key)){e.preventDefault();if($('#modal').open)return;run(async()=>{switch(e.key){case'F1':if(state.page!=='pos')await navigate('pos');setPanel('catalog');$('#search').focus();break;case'F2':if(state.page==='pos'&&state.cart.length)await completeSale([{method:'Cash',amount:totals(state.cart,state.discount).total}],true);break;case'F3':if(state.page==='pos'){state.method='UPI';setPanel('bill');renderCart();paymentModal()}break;case'F4':if(state.page==='pos')await hold();break;case'F8':await navigate('scanner');break}});return}
 if(e.key==='Enter'&&e.target.id==='search'){e.preventDefault();const q=state.query.trim().toLowerCase();if(!q)return;const p=state.products.find(p=>p.barcode===q||p.sku.toLowerCase()===q)||state.products.find(p=>p.name.toLowerCase().includes(q));if(p)run(async()=>{await addProduct(p.id);state.query='';$('#search').value='';renderProducts()});return}
 if(!typing&&!$('#modal').open&&state.page==='pos'){if(e.key==='Enter'&&barcodeBuffer.length>=3){const code=barcodeBuffer;barcodeBuffer='';const p=state.products.find(p=>p.barcode===code||p.sku===code);if(p)run(()=>addProduct(p.id));else toast('Scanned barcode is not in inventory.');e.preventDefault()}else if(e.key.length===1){if(Date.now()-barcodeLast>100)barcodeBuffer='';barcodeBuffer+=e.key;barcodeLast=Date.now()}}
});
for(const event of ['online','offline'])window.addEventListener(event,()=>{if($('#connection'))$('#connection').textContent=navigator.onLine?'Online · Saved locally':'Offline · Saved locally'});
async function start(){try{const route=location.hash.slice(1);if([...navItems.map(n=>n[0]),'settings'].includes(route))state.page=route;document.body.classList.toggle('dark',localStorage.getItem('speedbill-theme')==='dark');state.products=await init();const pref=await db.settings.get('preferences');if(pref)state.settings={...state.settings,...pref.value};if(state.settings.store==='SpeedBill Market'){state.settings.store='A1 TRADERS';await db.settings.put({key:'preferences',value:state.settings})}const draft=await db.drafts.get('active');if(draft){state.cart=draft.cart;state.discount=draft.discount;state.customer=draft.customer;state.customerTaxId=draft.customerTaxId||'';state.exchangeFor=draft.exchangeFor||''}else if(!await db.settings.get('demo-cart')){state.cart=state.products.filter(p=>['Farm Fresh Milk','Whole Wheat Bread','Free Range Eggs'].includes(p.name)).map(p=>({...p,qty:p.name==='Farm Fresh Milk'?2:1,discount:0}));await saveDraft();await db.settings.put({key:'demo-cart',value:true})}await refresh();shell();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Offline cache unavailable. Local data still saves on this device.'));}catch(e){console.error(e);$('#app').innerHTML=`<div class="boot"><div><h2>We couldn’t open local storage.</h2><p class="help">${esc(e.message)}</p><p class="help">Open with the included local server and allow browser storage.</p><button class="btn primary mt-4" onclick="location.reload()">Try again</button></div></div>`}}
const customerChannel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('speedbill-customer'):null;
function publishCustomer(){customerChannel?.postMessage({type:'cart',store:state.settings.store,customer:state.customer,...totals(state.cart,state.discount)})}
customerChannel?.addEventListener('message',e=>{if(e.data?.type==='ready')publishCustomer()});
function creditModal(){const total=totals(state.cart,state.discount).total;modal('Customer credit / part payment',`<form id="credit-form"><div class="notice">Total ${money(total)}. The unpaid amount stays in the customer credit ledger.</div><label class="mt-4">Customer name and phone / reference<input name="customer" value="${esc(state.customer)}" required maxlength="120"></label><label class="mt-4">Amount paid now (₹)<input name="paid" type="number" min="0" max="${total/100}" step="0.01" value="0" required></label><label class="mt-4">Paid using<select name="method"><option>Cash</option><option>Card</option><option>UPI</option></select></label><label class="mt-4"><input type="checkbox" required> Confirm the credit agreement and any payment received.</label><div class="modal-actions"><button class="btn primary">Save credit sale</button></div></form>`)}
async function approveLoss(lines){return new Promise(resolve=>{modal('Profit Guard: below-cost sale',`<div class="notice amber">Review before completing this sale.</div>${lines.map(l=>`<div class="list-row"><div>${esc(l.name)}<small>Minimum rate after current discounts: ${l.floor===null?'Discount must be reduced':money(l.floor)}</small></div><strong>Loss ${money(l.loss)}</strong></div>`).join('')}<div class="modal-actions"><button class="btn" id="loss-back">Go back</button><button class="btn danger" id="loss-approve">Approve below-cost sale</button></div>`);let done=false;const finish=v=>{if(done)return;done=true;$('#modal').removeEventListener('close',cancel);resolve(v)};const cancel=()=>finish(false);$('#modal').addEventListener('close',cancel,{once:true});$('#loss-back').onclick=()=>{finish(false);closeModal()};$('#loss-approve').onclick=async()=>{if(await managerApproval('Approve below-cost sale')){await log('Below-cost sale approved',lines.map(l=>l.name).join(', '));finish(true);closeModal()}}})}
setupOperations({modal,toast,actor:()=>state.settings.cashier,authorize:managerApproval});
setupBusiness({state,modal,toast,closeModal,refresh:async()=>{await refresh();renderPage()},shell,publish:publishCustomer,startExchange:async original=>{if(state.cart.length)await hold();state.exchangeFor=original;await saveDraft();await navigate('pos')},addReviewed:async rows=>{const grouped=new Map();for(const r of rows)grouped.set(r.id,(grouped.get(r.id)||0)+r.qty);rows=[...grouped].map(([id,qty])=>({id,qty}));for(const r of rows){const p=state.products.find(p=>p.id===r.id),old=state.cart.find(l=>l.id===r.id);if(!p||r.qty<=0||!Number.isFinite(r.qty)||(p.unit==='pcs'&&!Number.isInteger(r.qty))||(old?.qty||0)+r.qty>p.stock)throw Error('Check quantity and stock for each product.')}for(const r of rows){const p=state.products.find(p=>p.id===r.id),old=state.cart.find(l=>l.id===r.id);if(old)old.qty+=r.qty;else state.cart.push({...p,qty:r.qty,discount:0})}await saveDraft();closeModal();await navigate('pos');setPanel('bill')}});
start();

setupControl({state,modal,toast,closeModal,refresh:async()=>{await refresh();shell()},renderExtraction,receiptModal});

setupExperience({state,modal,toast,closeModal,navigate,addProduct});

async function saveStoreSettings(data){
 const next={...state.settings,...data};next.store=next.store.trim();next.cashier=next.cashier.trim();
 if(!next.store||!next.cashier)throw Error('Store and cashier names cannot be empty.');
 await db.transaction('rw',db.settings,db.audit,async()=>{await db.settings.put({key:'preferences',value:next});await audit('Store settings updated','Store identity and receipt preferences saved',next.cashier)});
 state.settings=next;applyStoreIdentity();
 const status=document.querySelector('#settings-save-status');if(status)status.textContent='All changes saved on this device';
}
function applyStoreIdentity(){
 document.title=state.settings.store+' · POS';
 const name=document.querySelector('.store-name');if(name)name.innerHTML=esc(state.settings.store)+'<small>Register 01</small>';
 const cashier=document.querySelector('.cashier strong');if(cashier)cashier.textContent=state.settings.cashier;
 const avatar=document.querySelector('.cashier .avatar');if(avatar)avatar.textContent=state.settings.cashier.split(' ').map(s=>s[0]).slice(0,2).join('');
}
let settingsQueue=Promise.resolve();
document.addEventListener('change',e=>{const form=e.target.closest('#settings-form');if(!form)return;if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form));settingsQueue=settingsQueue.then(async()=>{if(!await managerApproval('Save store settings'))return;await saveStoreSettings(data)}).catch(e=>toast(e.message,true))});
Dexie.liveQuery(()=>db.settings.get('preferences')).subscribe({next:row=>{if(row){state.settings={...state.settings,...row.value};applyStoreIdentity()}},error:e=>console.warn('Settings refresh unavailable',e.message)});
